int main() {
    for (std::uint64_t size=0; size<9; ++size)
        for (std::uint64_t off=0; off<9; ++off)
            for (std::uint64_t count=0; count<9; ++count)
                if (valid_range(off,count,size) != (off+count<=size)) return 2;
    const auto max = std::numeric_limits<std::uint64_t>::max();
    return !(valid_range(0,0,0) && valid_range(10,0,10) && !valid_range(11,0,10)
             && valid_range(1,9,10) && !valid_range(1,10,10)
             && valid_range(max,0,max) && !valid_range(max,1,max)
             && !valid_range(2,max,max) && valid_range(100,max-100,max));
}

