int main() {
    if (valid_component("") || valid_component(".") || valid_component("..")) return 1;
    if (!valid_component("oak-1.abc_X") || !valid_component("...")) return 2;
    if (valid_component(std::string_view("a\0b", 3)) || valid_component("a/b") || valid_component("a\\b")) return 3;
    for (unsigned i = 0; i < 256; ++i) {
        const auto value = static_cast<unsigned char>(i);
        const bool allowed = (value >= 'a' && value <= 'z') || (value >= 'A' && value <= 'Z') ||
                             (value >= '0' && value <= '9') || value == '.' || value == '_' || value == '-';
        const char bytes[] = {'a', static_cast<char>(value)};
        if (valid_component(std::string_view(bytes, 2)) != allowed) return 4;
    }
    return 0;
}

