#include <limits>
#include <random>
int main() {
    using I = std::pair<std::int64_t,std::int64_t>;
    using V = std::vector<I>;
    auto low = std::numeric_limits<std::int64_t>::min();
    auto high = std::numeric_limits<std::int64_t>::max();
    if (!merge_intervals({}).empty()) return 1;
    if (merge_intervals({{4,9},{1,3},{3,4},{12,13},{2,2},{9,1}}) != V{{1,9},{12,13}}) return 2;
    if (merge_intervals({{low,-1},{-1,high},{0,0}}) != V{{low,high}}) return 3;
    std::mt19937 rng(927);
    for (int trial = 0; trial < 400; ++trial) {
        V input;
        bool occupied[40]{};
        for (unsigned n = rng()%40; n; --n) {
            int a = int(rng()%41)-20, b = int(rng()%41)-20;
            input.push_back({a,b});
            for (int i=a; i<b; ++i) occupied[i+20]=true;
        }
        V expected;
        for (int i=0; i<40;) {
            if (!occupied[i]) {++i; continue;}
            int begin=i++;
            while (i<40 && occupied[i]) ++i;
            expected.push_back({begin-20,i-20});
        }
        if (merge_intervals(input) != expected) return 4;
    }
    return 0;
}

