#include <string>
#include <vector>
int main() {
    const std::string input("a\r\n\n\0b\nlast\r",12);
    const std::vector<std::string> expected{"a","",std::string("\0b",2),"last\r"};
    for (std::size_t first=0; first<=input.size(); ++first) {
        for (std::size_t second=first; second<=input.size(); ++second) {
            LineDecoder decoder;
            std::vector<std::string> got;
            auto drain = [&] { auto part=decoder.take(); got.insert(got.end(),part.begin(),part.end()); };
            decoder.feed(std::string_view(input).substr(0,first)); drain();
            decoder.feed(std::string_view(input).substr(first,second-first)); drain();
            decoder.feed(std::string_view(input).substr(second)); drain();
            decoder.finish(); drain();
            decoder.finish(); drain();
            if (got != expected) return 1;
            if (!decoder.take().empty()) return 2;
            decoder.feed("new\r\r\n");
            if (decoder.take() != std::vector<std::string>{"new\r"}) return 3;
            decoder.finish();
            if (!decoder.take().empty()) return 4;
        }
    }
    LineDecoder d;
    d.feed("x\n"); d.finish();
    if (d.take() != std::vector<std::string>{"x"}) return 5;
    return 0;
}
